D[38] = dict(title='دعای اعتذار', sub='پوزش از کوتاهی در حق مردم',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الِاعْتِذَارِ مِنْ تَبِعَاتِ الْعِبَادِ وَمِنَ التَّقْصِيرِ فِي حُقُوقِهِمْ وَفِي فَكَاكِ رَقَبَتِهِ مِنَ النَّارِ',
 intro_fa='از دعاهای امام سجاد (ع) در پوزش‌خواهی از حقوقی که از بندگان بر گردن دارد، و از کوتاهی در حقوق آنان، و برای رهایی خود از آتش',
 p=[
('اللَّهُمَّ إِنِّي أَعْتَذِرُ إِلَيْكَ مِنْ مَظْلُومٍ ظُلِمَ بِحَضْرَتِي فَلَمْ أَنْصُرْهُ، وَمِنْ مَعْرُوفٍ أُسْدِيَ إِلَيَّ فَلَمْ أَشْكُرْهُ، وَمِنْ مُسِيءٍ اعْتَذَرَ إِلَيَّ فَلَمْ أَعْذِرْهُ،',
 'خدایا، از تو پوزش می‌خواهم از ستم‌دیده‌ای که در حضور من به او ستم شد و یاری‌اش نکردم، و از نیکی‌ای که به من شد و سپاسش نگزاردم، و از بدکاری که از من پوزش خواست و عذرش را نپذیرفتم،'),
('وَمِنْ ذِي فَاقَةٍ سَأَلَنِي فَلَمْ أُوثِرْهُ، وَمِنْ حَقِّ ذِي حَقٍّ لَزِمَنِي لِمُؤْمِنٍ فَلَمْ أُوَفِّرْهُ، وَمِنْ عَيْبِ مُؤْمِنٍ ظَهَرَ لِي فَلَمْ أَسْتُرْهُ، وَمِنْ كُلِّ إِثْمٍ عَرَضَ لِي فَلَمْ أَهْجُرْهُ.',
 'و از نیازمندی که از من خواست و او را بر خود مقدّم نداشتم، و از حقِ صاحب‌حقی از مؤمنان که بر گردنم بود و آن را کامل نپرداختم، و از عیب مؤمنی که بر من آشکار شد و آن را نپوشاندم، و از هر گناهی که پیش رویم آمد و از آن دوری نکردم.'),
('أَعْتَذِرُ إِلَيْكَ يَا إِلَهِي مِنْهُنَّ وَمِنْ نَظَائِرِهِنَّ اعْتِذَارَ نَدَامَةٍ يَكُونُ وَاعِظاً لِمَا بَيْنَ يَدَيَّ مِنْ أَشْبَاهِهِنَّ.',
 'معبودا، از این‌ها و مانندهای آن‌ها از تو پوزش می‌خواهم؛ پوزشی از سرِ پشیمانی، که مرا از همانندهای آن‌ها که پیش رو دارم باز دارد.'),
('فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ نَدَامَتِي عَلَى مَا وَقَعْتُ فِيهِ مِنَ الزَّلَّاتِ، وَعَزْمِي عَلَى تَرْكِ مَا يَعْرِضُ لِي مِنَ السَّيِّئَاتِ، تَوْبَةً تُوجِبُ لِي مَحَبَّتَكَ، يَا مُحِبَّ التَّوَّابِينَ.',
 'پس بر محمد و خاندانش درود فرست، و پشیمانی‌ام را از لغزش‌هایی که در آن افتادم، و عزمم را بر ترک بدی‌هایی که پیش رویم می‌آید، توبه‌ای قرار ده که محبت تو را برایم واجب کند؛ ای دوستدار توبه‌کنندگان.'),
])

D[12] = dict(title='دعای اعتراف', sub='اعتراف به گناه و درخواست توبه',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الِاعْتِرَافِ وَطَلَبِ التَّوْبَةِ إِلَى اللَّهِ تَعَالَى',
 intro_fa='از دعاهای امام سجاد (ع) در اعتراف [به گناه] و درخواست توبه به سوی خدای متعال',
 p=[
('اللَّهُمَّ إِنَّهُ يَحْجُبُنِي عَنْ مَسْأَلَتِكَ خِلَالٌ ثَلَاثٌ، وَتَحْدُونِي عَلَيْهَا خَلَّةٌ وَاحِدَةٌ:',
 'خدایا، سه خصلت مرا از درخواست از تو باز می‌دارد، و یک خصلت مرا به آن وا می‌دارد:'),
('يَحْجُبُنِي أَمْرٌ أَمَرْتَ بِهِ فَأَبْطَأْتُ عَنْهُ، وَنَهْيٌ نَهَيْتَنِي عَنْهُ فَأَسْرَعْتُ إِلَيْهِ، وَنِعْمَةٌ أَنْعَمْتَ بِهَا عَلَيَّ فَقَصَّرْتُ فِي شُكْرِهَا.',
 'باز می‌دارد مرا فرمانی که دادی و من در [انجام] آن کندی کردم، و نهیی که مرا از آن باز داشتی و من به سویش شتافتم، و نعمتی که به من بخشیدی و در سپاسش کوتاهی کردم.'),
('وَيَحْدُونِي عَلَى مَسْأَلَتِكَ تَفَضُّلُكَ عَلَى مَنْ أَقْبَلَ بِوَجْهِهِ إِلَيْكَ، وَوَفَدَ بِحُسْنِ ظَنِّهِ إِلَيْكَ؛ إِذْ جَمِيعُ إِحْسَانِكَ تَفَضُّلٌ، وَإِذْ كُلُّ نِعَمِكَ ابْتِدَاءٌ.',
 'و مرا به درخواست از تو وا می‌دارد بخشش تو بر کسی که رو به سوی تو آورد و با گمان نیکش بر تو وارد شد؛ زیرا همهٔ نیکی‌ات بخشش [بی‌استحقاق] است، و همهٔ نعمت‌هایت آغازین [و بی‌سابقهٔ عمل].'),
('فَهَا أَنَا ذَا، يَا إِلَهِي، وَاقِفٌ بِبَابِ عِزِّكَ وُقُوفَ الْمُسْتَسْلِمِ الذَّلِيلِ، وَسَائِلُكَ عَلَى الْحَيَاءِ مِنِّي سُؤَالَ الْبَائِسِ الْمُعِيلِ،',
 'پس اینک من، ای معبودم، بر درگاه عزّتت ایستاده‌ام، ایستادنِ تسلیم‌شدهٔ خوار، و با شرمی که دارم از تو می‌خواهم، خواستنِ درماندهٔ عیالمند؛'),
('مُقِرٌّ لَكَ بِأَنِّي لَمْ أَسْتَسْلِمْ وَقْتَ إِحْسَانِكَ إِلَّا بِالْإِقْلَاعِ عَنْ عِصْيَانِكَ، وَلَمْ أَخْلُ فِي الْحَالَاتِ كُلِّهَا مِنِ امْتِنَانِكَ.',
 'به تو اقرار دارم که هنگام نیکی‌ات [به من]، تسلیم [فرمانت] نشدم جز با دست کشیدنی [ناپایدار] از نافرمانی‌ات، و در هیچ حالی از نعمت‌بخشی تو خالی نبوده‌ام.'),
('فَهَلْ يَنْفَعُنِي، يَا إِلَهِي، إِقْرَارِي عِنْدَكَ بِسُوءِ مَا اكْتَسَبْتُ؟ وَهَلْ يُنْجِينِي مِنْكَ اعْتِرَافِي لَكَ بِقَبِيحِ مَا ارْتَكَبْتُ؟ أَمْ أَوْجَبْتَ لِي فِي مَقَامِي هَذَا سُخْطَكَ؟ أَمْ لَزِمَنِي فِي وَقْتِ دُعَايَ مَقْتُكَ؟',
 'آیا، ای معبودم، اقرارم نزد تو به بدیِ آنچه به دست آوردم سودم می‌دهد؟ و آیا اعترافم نزد تو به زشتیِ آنچه مرتکب شدم مرا از [عذاب] تو می‌رهاند؟ یا در این جایگاهم خشمت را بر من واجب کرده‌ای؟ یا در هنگام دعایم بیزاری‌ات دامنگیرم شده است؟'),
('سُبْحَانَكَ، لَا أَيْأَسُ مِنْكَ وَقَدْ فَتَحْتَ لِي بَابَ التَّوْبَةِ إِلَيْكَ، بَلْ أَقُولُ مَقَالَ الْعَبْدِ الذَّلِيلِ الظَّالِمِ لِنَفْسِهِ، الْمُسْتَخِفِّ بِحُرْمَةِ رَبِّهِ،',
 'پاکی از آنِ توست؛ از تو نومید نمی‌شوم، در حالی که درِ توبه به سوی خودت را بر من گشوده‌ای؛ بلکه سخن می‌گویم همچون سخن بندهٔ خوارِ ستمکار بر خویش، که حرمت پروردگارش را سبک شمرده؛'),
('الَّذِي عَظُمَتْ ذُنُوبُهُ فَجَلَّتْ، وَأَدْبَرَتْ أَيَّامُهُ فَوَلَّتْ، حَتَّى إِذَا رَأَى مُدَّةَ الْعَمَلِ قَدِ انْقَضَتْ، وَغَايَةَ الْعُمُرِ قَدِ انْتَهَتْ، وَأَيْقَنَ أَنَّهُ لَا مَحِيصَ لَهُ مِنْكَ، وَلَا مَهْرَبَ لَهُ عَنْكَ،',
 'کسی که گناهانش بزرگ شد و سنگین گشت، و روزهایش پشت کرد و گذشت؛ تا آنگاه که دید مهلت عمل به سر رسیده و پایان عمر فرا رسیده، و یقین کرد که از تو گریزگاهی ندارد و از [دسترس] تو راه فراری نیست،'),
('تَلَقَّاكَ بِالْإِنَابَةِ، وَأَخْلَصَ لَكَ التَّوْبَةَ، فَقَامَ إِلَيْكَ بِقَلْبٍ طَاهِرٍ نَقِيٍّ، ثُمَّ دَعَاكَ بِصَوْتٍ حَائِلٍ خَفِيٍّ،',
 'با بازگشت به سوی تو رو آورد، و توبه را برایت خالص کرد، و با دلی پاک و پیراسته به پیشگاهت ایستاد، سپس با صدایی لرزان و آهسته تو را خواند؛'),
('قَدْ تَطَأْطَأَ لَكَ فَانْحَنَى، وَنَكَّسَ رَأْسَهُ فَانْثَنَى، قَدْ أَرْعَشَتْ خَشْيَتُهُ رِجْلَيْهِ، وَغَرَّقَتْ دُمُوعُهُ خَدَّيْهِ،',
 'در برابرت فروتنانه خم شده و دوتا گشته، و سرش را به زیر افکنده و درهم شکسته؛ ترس [از تو] پاهایش را لرزانده، و اشک‌هایش گونه‌هایش را غرق کرده؛'),
('يَدْعُوكَ: بِيَا أَرْحَمَ الرَّاحِمِينَ، وَيَا أَرْحَمَ مَنِ انْتَابَهُ الْمُسْتَرْحِمُونَ، وَيَا أَعْطَفَ مَنْ أَطَافَ بِهِ الْمُسْتَغْفِرُونَ، وَيَا مَنْ عَفْوُهُ أَكْثَرُ مِنْ نَقِمَتِهِ، وَيَا مَنْ رِضَاهُ أَوْفَرُ مِنْ سَخَطِهِ،',
 'تو را می‌خواند: «ای مهربان‌ترینِ مهربانان، و ای مهربان‌ترین کسی که رحمت‌جویان پیاپی به او رو می‌آورند، و ای پرعطوفت‌ترین کسی که آمرزش‌خواهان گِرد او می‌گردند، و ای که گذشتش از انتقامش بیشتر است، و ای که خشنودی‌اش از خشمش افزون‌تر است،'),
('وَيَا مَنْ تَحَمَّدَ إِلَى خَلْقِهِ بِحُسْنِ التَّجَاوُزِ، وَيَا مَنْ عَوَّدَ عِبَادَهُ قَبُولَ الْإِنَابَةِ، وَيَا مَنِ اسْتَصْلَحَ فَاسِدَهُمْ بِالتَّوْبَةِ، وَيَا مَنْ رَضِيَ مِنْ فِعْلِهِمْ بِالْيَسِيرِ، وَيَا مَنْ كَافَى قَلِيلَهُمْ بِالْكَثِيرِ،',
 'و ای که با گذشتِ نیکو نزد آفریدگانش ستوده شده، و ای که بندگانش را به پذیرفتن بازگشت [آنان] عادت داده، و ای که تباهِ آنان را با توبه به صلاح آورده، و ای که از کردارشان به اندک خشنود شده، و ای که [کارِ] اندکشان را با بسیار پاداش داده،'),
('وَيَا مَنْ ضَمِنَ لَهُمْ إِجَابَةَ الدُّعَاءِ، وَيَا مَنْ وَعَدَهُمْ عَلَى نَفْسِهِ بِتَفَضُّلِهِ حُسْنَ الْجَزَاءِ.',
 'و ای که اجابتِ دعا را برایشان ضمانت کرده، و ای که از روی بخشش، پاداش نیکو را بر عهدهٔ خود به آنان وعده داده است.»'),
('مَا أَنَا بِأَعْصَى مَنْ عَصَاكَ فَغَفَرْتَ لَهُ، وَمَا أَنَا بِأَلْوَمِ مَنِ اعْتَذَرَ إِلَيْكَ فَقَبِلْتَ مِنْهُ، وَمَا أَنَا بِأَظْلَمِ مَنْ تَابَ إِلَيْكَ فَعُدْتَ عَلَيْهِ.',
 'من نافرمان‌تر از کسی که تو را نافرمانی کرد و او را آمرزیدی نیستم، و سرزنش‌پذیرتر از کسی که از تو پوزش خواست و از او پذیرفتی نیستم، و ستمکارتر از کسی که به سوی تو توبه کرد و تو [با رحمت] به او بازگشتی نیستم.'),
('أَتُوبُ إِلَيْكَ فِي مَقَامِي هَذَا تَوْبَةَ نَادِمٍ عَلَى مَا فَرَطَ مِنْهُ، مُشْفِقٍ مِمَّا اجْتَمَعَ عَلَيْهِ، خَالِصِ الْحَيَاءِ مِمَّا وَقَعَ فِيهِ،',
 'در این جایگاهم به سوی تو توبه می‌کنم؛ توبهٔ کسی که از آنچه از او سر زده پشیمان است، از آنچه بر [دوش] او گرد آمده بیمناک است، و از آنچه در آن افتاده سراپا شرمسار است؛'),
('عَالِمٍ بِأَنَّ الْعَفْوَ عَنِ الذَّنْبِ الْعَظِيمِ لَا يَتَعَاظَمُكَ، وَأَنَّ التَّجَاوُزَ عَنِ الْإِثْمِ الْجَلِيلِ لَا يَسْتَصْعِبُكَ، وَأَنَّ احْتِمَالَ الْجِنَايَاتِ الْفَاحِشَةِ لَا يَتَكَأَّدُكَ،',
 'و می‌داند که گذشتن از گناه بزرگ برای تو بزرگ نیست، و درگذشتن از گناهِ سنگین بر تو دشوار نیست، و تحمّلِ جنایت‌های زشت تو را به رنج نمی‌اندازد؛'),
('وَأَنَّ أَحَبَّ عِبَادِكَ إِلَيْكَ مَنْ تَرَكَ الِاسْتِكْبَارَ عَلَيْكَ، وَجَانَبَ الْإِصْرَارَ، وَلَزِمَ الِاسْتِغْفَارَ.',
 'و [می‌داند] که محبوب‌ترین بندگانت نزد تو کسی است که گردن‌کشی در برابر تو را رها کند، و از پافشاری [بر گناه] دوری کند، و همواره آمرزش بخواهد.'),
('وَأَنَا أَبْرَأُ إِلَيْكَ مِنْ أَنْ أَسْتَكْبِرَ، وَأَعُوذُ بِكَ مِنْ أَنْ أُصِرَّ، وَأَسْتَغْفِرُكَ لِمَا قَصَّرْتُ فِيهِ، وَأَسْتَعِينُ بِكَ عَلَى مَا عَجَزْتُ عَنْهُ.',
 'و من به پیشگاهت از اینکه گردن‌کشی کنم بیزاری می‌جویم، و به تو پناه می‌برم از اینکه [بر گناه] پافشاری کنم، و برای آنچه در آن کوتاهی کردم از تو آمرزش می‌خواهم، و بر آنچه از آن ناتوانم از تو یاری می‌جویم.'),
('اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَهَبْ لِي مَا يَجِبُ عَلَيَّ لَكَ، وَعَافِنِي مِمَّا أَسْتَوْجِبُهُ مِنْكَ، وَأَجِرْنِي مِمَّا يَخَافُهُ أَهْلُ الْإِسَاءَةِ،',
 'خدایا، بر محمد و خاندانش درود فرست، و آنچه را از حقِ تو بر گردن من است به من ببخش، و از آنچه [از کیفر] که از تو سزاوارش هستم عافیتم ده، و از آنچه بدکاران از آن می‌ترسند پناهم ده؛'),
('فَإِنَّكَ مَلِيءٌ بِالْعَفْوِ، مَرْجُوٌّ لِلْمَغْفِرَةِ، مَعْرُوفٌ بِالتَّجَاوُزِ، لَيْسَ لِحَاجَتِي مَطْلَبٌ سِوَاكَ، وَلَا لِذَنْبِي غَافِرٌ غَيْرُكَ، حَاشَاكَ، وَلَا أَخَافُ عَلَى نَفْسِي إِلَّا إِيَّاكَ، إِنَّكَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ.',
 'زیرا تو سرشار از گذشتی، برای آمرزش امید بسته شده‌ای، و به درگذشتن شناخته‌شده‌ای؛ برای نیازم جز تو جای درخواستی نیست، و برای گناهم آمرزنده‌ای جز تو نیست ــ هرگز [جز تو نیست] ــ و بر جانم جز از تو نمی‌ترسم؛ همانا تو سزاوار پروا و سزاوار آمرزشی.'),
('صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَاقْضِ حَاجَتِي، وَأَنْجِحْ طَلِبَتِي، وَاغْفِرْ ذَنْبِي، وَآمِنْ خَوْفَ نَفْسِي، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَذَلِكَ عَلَيْكَ يَسِيرٌ، آمِينَ رَبَّ الْعَالَمِينَ.',
 'بر محمد و خاندان محمد درود فرست، و حاجتم را برآور، و خواسته‌ام را روا کن، و گناهم را بیامرز، و ترسِ جانم را به ایمنی بدل کن؛ همانا تو بر هر چیزی توانایی، و این بر تو آسان است. آمین، ای پروردگار جهانیان.'),
])

D[31] = dict(title='دعای توبه', sub='یاد توبه و درخواست آن',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي ذِكْرِ التَّوْبَةِ وَطَلَبِهَا',
 intro_fa='از دعاهای امام سجاد (ع) در یاد توبه و درخواست آن',
 p=[
('اللَّهُمَّ يَا مَنْ لَا يَصِفُهُ نَعْتُ الْوَاصِفِينَ، وَيَا مَنْ لَا يُجَاوِزُهُ رَجَاءُ الرَّاجِينَ، وَيَا مَنْ لَا يَضِيعُ لَدَيْهِ أَجْرُ الْمُحْسِنِينَ، وَيَا مَنْ هُوَ مُنْتَهَى خَوْفِ الْعَابِدِينَ، وَيَا مَنْ هُوَ غَايَةُ خَشْيَةِ الْمُتَّقِينَ،',
 'خدایا، ای که توصیفِ توصیف‌کنندگان او را وصف نمی‌کند، و ای که امیدِ امیدواران از او فراتر نمی‌رود، و ای که پاداش نیکوکاران نزد او تباه نمی‌شود، و ای که نهایتِ ترسِ عبادت‌کنندگان است، و ای که پایانِ بیمِ پرهیزگاران است؛'),
('هَذَا مَقَامُ مَنْ تَدَاوَلَتْهُ أَيْدِي الذُّنُوبِ، وَقَادَتْهُ أَزِمَّةُ الْخَطَايَا، وَاسْتَحْوَذَ عَلَيْهِ الشَّيْطَانُ، فَقَصَّرَ عَمَّا أَمَرْتَ بِهِ تَفْرِيطاً، وَتَعَاطَى مَا نَهَيْتَ عَنْهُ تَغْرِيراً،',
 'این جایگاهِ کسی است که دست‌های گناهان او را دست‌به‌دست کرده، و مهارهای خطاها او را کشانده، و شیطان بر او چیره گشته است؛ پس از روی سهل‌انگاری در آنچه فرمان دادی کوتاهی کرد، و از روی فریب‌خوردگی به آنچه نهی کردی دست زد؛'),
('كَالْجَاهِلِ بِقُدْرَتِكَ عَلَيْهِ، أَوْ كَالْمُنْكِرِ فَضْلَ إِحْسَانِكَ إِلَيْهِ، حَتَّى إِذَا انْفَتَحَ لَهُ بَصَرُ الْهُدَى، وَتَقَشَّعَتْ عَنْهُ سَحَائِبُ الْعَمَى،',
 'همچون کسی که از توانایی تو بر خود بی‌خبر است، یا همچون کسی که فزونیِ نیکی تو به خود را انکار می‌کند؛ تا آنگاه که چشمِ هدایت برایش گشوده شد، و ابرهای کوردلی از او پراکنده گشت؛'),
('أَحْصَى مَا ظَلَمَ بِهِ نَفْسَهُ، وَفَكَّرَ فِيمَا خَالَفَ بِهِ رَبَّهُ، فَرَأَى كَبِيرَ عِصْيَانِهِ كَبِيراً، وَجَلِيلَ مُخَالَفَتِهِ جَلِيلاً،',
 'آنچه را با آن به خود ستم کرده بود برشمرد، و در آنچه با آن با پروردگارش مخالفت کرده بود اندیشید؛ پس نافرمانیِ بزرگش را بزرگ دید، و مخالفتِ سنگینش را سنگین یافت؛'),
('فَأَقْبَلَ نَحْوَكَ مُؤَمِّلاً لَكَ، مُسْتَحْيِياً مِنْكَ، وَوَجَّهَ رَغْبَتَهُ إِلَيْكَ ثِقَةً بِكَ، فَأَمَّكَ بِطَمَعِهِ يَقِيناً، وَقَصَدَكَ بِخَوْفِهِ إِخْلَاصاً،',
 'پس امیدوار به تو و شرمسار از تو، رو به سویت آورد، و از سرِ اعتماد به تو، اشتیاقش را به سوی تو گرداند؛ با یقین، با طمعش آهنگ تو کرد، و با اخلاص، با ترسش تو را قصد کرد؛'),
('قَدْ خَلَا طَمَعُهُ مِنْ كُلِّ مَطْمُوعٍ فِيهِ غَيْرِكَ، وَأَفْرَخَ رَوْعُهُ مِنْ كُلِّ مَحْذُورٍ مِنْهُ سِوَاكَ،',
 'طمعش از هر کسی جز تو که بتوان به او طمع بست تهی شده، و ترسش از هر کسی جز تو که بتوان از او پرهیز کرد فرو نشسته است؛'),
('فَمَثَلَ بَيْنَ يَدَيْكَ مُتَضَرِّعاً، وَغَمَّضَ بَصَرَهُ إِلَى الْأَرْضِ مُتَخَشِّعاً، وَطَأْطَأَ رَأْسَهُ لِعِزَّتِكَ مُتَذَلِّلاً،',
 'پس زاری‌کنان در برابرت ایستاد، و فروتنانه چشمش را به زمین دوخت و فرو بست، و با خواری سرش را در برابر عزّتت به زیر افکند؛'),
('وَأَبَثَّكَ مِنْ سِرِّهِ مَا أَنْتَ أَعْلَمُ بِهِ مِنْهُ خُضُوعاً، وَعَدَّدَ مِنْ ذُنُوبِهِ مَا أَنْتَ أَحْصَى لَهَا خُشُوعاً، وَاسْتَغَاثَ بِكَ مِنْ عَظِيمِ مَا وَقَعَ بِهِ فِي عِلْمِكَ، وَقَبِيحِ مَا فَضَحَهُ فِي حُكْمِكَ،',
 'و با فروتنی از رازش آنچه را تو از خودش به آن داناتری با تو در میان نهاد، و با خشوع از گناهانش آنچه را تو بهتر برمی‌شماری یک‌یک برشمرد، و از [گناهِ] بزرگی که در علم تو در آن افتاده، و [کارِ] زشتی که در داوری تو رسوایش کرده، به تو پناه آورد؛'),
('مِنْ ذُنُوبٍ أَدْبَرَتْ لَذَّاتُهَا فَذَهَبَتْ، وَأَقَامَتْ تَبِعَاتُهَا فَلَزِمَتْ،',
 'از گناهانی که لذت‌هایشان پشت کرد و رفت، و پیامدهایشان ماند و دامنگیر شد؛'),
('وَلَا يُنْكِرُ يَا إِلَهِي عَدْلَكَ إِنْ عَاقَبْتَهُ، وَلَا يَسْتَعْظِمُ عَفْوَكَ إِنْ عَفَوْتَ عَنْهُ وَرَحِمْتَهُ، لِأَنَّكَ الرَّبُّ الْكَرِيمُ الَّذِي لَا يَتَعَاظَمُهُ غُفْرَانُ الذَّنْبِ الْعَظِيمِ.',
 'و ای معبودم، اگر کیفرش کنی عدل تو را انکار نمی‌کند، و اگر از او بگذری و بر او رحم کنی، گذشتت را بزرگ نمی‌شمارد؛ زیرا تو پروردگار بزرگواری هستی که آمرزیدنِ گناه بزرگ برایش بزرگ نیست.'),
('اللَّهُمَّ فَهَا أَنَا ذَا قَدْ جِئْتُكَ مُطِيعاً لِأَمْرِكَ فِيمَا أَمَرْتَ بِهِ مِنَ الدُّعَاءِ، مُتَنَجِّزاً وَعْدَكَ فِيمَا وَعَدْتَ بِهِ مِنَ الْإِجَابَةِ، إِذْ تَقُولُ: ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾.',
 'خدایا، اینک من نزد تو آمده‌ام، فرمان‌بردار امرت در آنچه از دعا فرمان دادی، و خواهانِ وفای وعده‌ات در آنچه از اجابت وعده دادی؛ آنجا که می‌گویی: «مرا بخوانید تا شما را اجابت کنم».'),
('اللَّهُمَّ فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَالْقَنِي بِمَغْفِرَتِكَ كَمَا لَقِيتُكَ بِإِقْرَارِي، وَارْفَعْنِي عَنْ مَصَارِعِ الذُّنُوبِ كَمَا وَضَعْتُ لَكَ نَفْسِي، وَاسْتُرْنِي بِسِتْرِكَ كَمَا تَأَنَّيْتَنِي عَنِ الِانْتِقَامِ مِنِّي.',
 'خدایا، پس بر محمد و خاندانش درود فرست، و با آمرزشت با من روبه‌رو شو، همان‌گونه که من با اقرارم با تو روبه‌رو شدم؛ و مرا از زمین‌خوردنگاه‌های گناهان بالا بر، همان‌گونه که خود را برای تو فرو نهادم؛ و با پوششت مرا بپوشان، همان‌گونه که در انتقام گرفتن از من درنگ کردی.'),
('اللَّهُمَّ وَثَبِّتْ فِي طَاعَتِكَ نِيَّتِي، وَأَحْكِمْ فِي عِبَادَتِكَ بَصِيرَتِي، وَوَفِّقْنِي مِنَ الْأَعْمَالِ لِمَا تَغْسِلُ بِهِ دَنَسَ الْخَطَايَا عَنِّي، وَتَوَفَّنِي عَلَى مِلَّتِكَ وَمِلَّةِ نَبِيِّكَ مُحَمَّدٍ عَلَيْهِ السَّلَامُ إِذَا تَوَفَّيْتَنِي.',
 'خدایا، نیّتم را در فرمان‌برداری‌ات استوار کن، و بینشم را در بندگی‌ات محکم گردان، و مرا به کارهایی موفق بدار که با آن چرکِ خطاها را از من بشویی، و هنگامی که جانم را می‌گیری، مرا بر آیین خودت و آیین پیامبرت محمد ــ که درود بر او باد ــ بمیران.'),
('اللَّهُمَّ إِنِّي أَتُوبُ إِلَيْكَ فِي مَقَامِي هَذَا مِنْ كَبَائِرِ ذُنُوبِي وَصَغَائِرِهَا، وَبَوَاطِنِ سَيِّئَاتِي وَظَوَاهِرِهَا، وَسَوَالِفِ زَلَّاتِي وَحَوَادِثِهَا،',
 'خدایا، من در این جایگاهم به سوی تو توبه می‌کنم از گناهان بزرگ و کوچکم، و از بدی‌های پنهان و آشکارم، و از لغزش‌های گذشته و تازه‌ام؛'),
('تَوْبَةَ مَنْ لَا يُحَدِّثُ نَفْسَهُ بِمَعْصِيَةٍ، وَلَا يُضْمِرُ أَنْ يَعُودَ فِي خَطِيئَةٍ.',
 'توبهٔ کسی که با خود از نافرمانی سخن نمی‌گوید، و در دل ندارد که به خطایی بازگردد.'),
('وَقَدْ قُلْتَ يَا إِلَهِي فِي مُحْكَمِ كِتَابِكَ: إِنَّكَ تَقْبَلُ التَّوْبَةَ عَنْ عِبَادِكَ، وَتَعْفُو عَنِ السَّيِّئَاتِ، وَتُحِبُّ التَّوَّابِينَ؛ فَاقْبَلْ تَوْبَتِي كَمَا وَعَدْتَ، وَاعْفُ عَنْ سَيِّئَاتِي كَمَا ضَمِنْتَ، وَأَوْجِبْ لِي مَحَبَّتَكَ كَمَا شَرَطْتَ.',
 'و تو، ای معبودم، در کتاب استوارت فرموده‌ای که توبه را از بندگانت می‌پذیری، و از بدی‌ها درمی‌گذری، و توبه‌کنندگان را دوست داری؛ پس توبه‌ام را بپذیر چنان‌که وعده دادی، و از بدی‌هایم درگذر چنان‌که ضمانت کردی، و محبتت را برایم واجب کن چنان‌که شرط نهادی.'),
('وَلَكَ يَا رَبِّ شَرْطِي أَلَّا أَعُودَ فِي مَكْرُوهِكَ، وَضَمَانِي أَنْ لَا أَرْجِعَ فِي مَذْمُومِكَ، وَعَهْدِي أَنْ أَهْجُرَ جَمِيعَ مَعَاصِيكَ.',
 'و ای پروردگارم، شرطِ من با تو این است که به آنچه ناپسند می‌داری بازنگردم، و ضمانتم این است که به آنچه نکوهیده می‌شماری برنگردم، و پیمانم این است که از همهٔ نافرمانی‌هایت دوری کنم.'),
('اللَّهُمَّ إِنَّكَ أَعْلَمُ بِمَا عَمِلْتُ، فَاغْفِرْ لِي مَا عَلِمْتَ، وَاصْرِفْنِي بِقُدْرَتِكَ إِلَى مَا أَحْبَبْتَ.',
 'خدایا، تو به آنچه کرده‌ام داناتری؛ پس آنچه را می‌دانی بر من ببخشای، و با قدرتت مرا به سوی آنچه دوست داری بگردان.'),
('اللَّهُمَّ وَعَلَيَّ تَبِعَاتٌ قَدْ حَفِظْتُهُنَّ، وَتَبِعَاتٌ قَدْ نَسِيتُهُنَّ، وَكُلُّهُنَّ بِعَيْنِكَ الَّتِي لَا تَنَامُ، وَعِلْمِكَ الَّذِي لَا يَنْسَى،',
 'خدایا، حقوقی [از دیگران] بر گردن من است که آن‌ها را به یاد دارم، و حقوقی که فراموششان کرده‌ام؛ و همهٔ آن‌ها در برابر دیدهٔ توست که نمی‌خوابد، و دانش توست که فراموش نمی‌کند؛'),
('فَعَوِّضْ مِنْهَا أَهْلَهَا، وَاحْطُطْ عَنِّي وِزْرَهَا، وَخَفِّفْ عَنِّي ثِقْلَهَا، وَاعْصِمْنِي مِنْ أَنْ أُقَارِفَ مِثْلَهَا.',
 'پس به صاحبانشان در برابر آن‌ها عوض ده، و بارِ گناهشان را از من فرو نه، و سنگینی‌شان را از من سبک کن، و مرا از اینکه مانند آن‌ها را مرتکب شوم نگاه دار.'),
('اللَّهُمَّ وَإِنَّهُ لَا وَفَاءَ لِي بِالتَّوْبَةِ إِلَّا بِعِصْمَتِكَ، وَلَا اسْتِمْسَاكَ بِي عَنِ الْخَطَايَا إِلَّا عَنْ قُوَّتِكَ، فَقَوِّنِي بِقُوَّةٍ كَافِيَةٍ، وَتَوَلَّنِي بِعِصْمَةٍ مَانِعَةٍ.',
 'خدایا، مرا وفای به توبه نیست مگر با نگه‌داری تو، و مرا خودداری از خطاها نیست مگر از نیروی تو؛ پس مرا با نیرویی بسنده نیرومند کن، و با نگه‌داری‌ای بازدارنده سرپرستی‌ام کن.'),
('اللَّهُمَّ أَيُّمَا عَبْدٍ تَابَ إِلَيْكَ وَهُوَ فِي عِلْمِ الْغَيْبِ عِنْدَكَ فَاسِخٌ لِتَوْبَتِهِ، وَعَائِدٌ فِي ذَنْبِهِ وَخَطِيئَتِهِ، فَإِنِّي أَعُوذُ بِكَ أَنْ أَكُونَ كَذَلِكَ،',
 'خدایا، هر بنده‌ای که به سوی تو توبه کند، در حالی که در علم غیبِ تو شکنندهٔ توبه‌اش و بازگردنده به گناه و خطایش باشد، من به تو پناه می‌برم از اینکه چنین باشم؛'),
('فَاجْعَلْ تَوْبَتِي هَذِهِ تَوْبَةً لَا أَحْتَاجُ بَعْدَهَا إِلَى تَوْبَةٍ، تَوْبَةً مُوجِبَةً لِمَحْوِ مَا سَلَفَ، وَالسَّلَامَةِ فِيمَا بَقِيَ.',
 'پس این توبه‌ام را توبه‌ای قرار ده که پس از آن به توبه‌ای نیاز نداشته باشم؛ توبه‌ای که پاک شدنِ گذشته و سلامت در باقی‌مانده [ی عمر] را واجب کند.'),
('اللَّهُمَّ إِنِّي أَعْتَذِرُ إِلَيْكَ مِنْ جَهْلِي، وَأَسْتَوْهِبُكَ سُوءَ فِعْلِي، فَاضْمُمْنِي إِلَى كَنَفِ رَحْمَتِكَ تَطَوُّلاً، وَاسْتُرْنِي بِسِتْرِ عَافِيَتِكَ تَفَضُّلاً.',
 'خدایا، از نادانی‌ام از تو پوزش می‌خواهم، و بخششِ کردار بدم را از تو می‌طلبم؛ پس از روی احسان مرا در پناه رحمتت جای ده، و از روی بخشش مرا با پوشش عافیتت بپوشان.'),
('اللَّهُمَّ وَإِنِّي أَتُوبُ إِلَيْكَ مِنْ كُلِّ مَا خَالَفَ إِرَادَتَكَ، أَوْ زَالَ عَنْ مَحَبَّتِكَ، مِنْ خَطَرَاتِ قَلْبِي، وَلَحَظَاتِ عَيْنِي، وَحِكَايَاتِ لِسَانِي،',
 'خدایا، من به سوی تو توبه می‌کنم از هر آنچه با خواست تو مخالف بود یا از محبت تو دور افتاد، از گذرهای دلم، و نگاه‌های چشمم، و گفته‌های زبانم؛'),
('تَوْبَةً تَسْلَمُ بِهَا كُلُّ جَارِحَةٍ عَلَى حِيَالِهَا مِنْ تَبِعَاتِكَ، وَتَأْمَنُ مِمَّا يَخَافُ الْمُعْتَدُونَ مِنْ أَلِيمِ سَطَوَاتِكَ.',
 'توبه‌ای که با آن هر عضوی به‌تنهایی از پیامدهای [کیفر] تو سالم بماند، و از کیفرهای دردناکت که تجاوزکاران از آن می‌ترسند ایمن گردد.'),
('اللَّهُمَّ فَارْحَمْ وَحْدَتِي بَيْنَ يَدَيْكَ، وَوَجِيبَ قَلْبِي مِنْ خَشْيَتِكَ، وَاضْطِرَابَ أَرْكَانِي مِنْ هَيْبَتِكَ،',
 'خدایا، پس بر تنهایی‌ام در پیشگاهت، و تپش دلم از بیم تو، و لرزش اندامم از هیبت تو رحم کن؛'),
('فَقَدْ أَقَامَتْنِي يَا رَبِّ ذُنُوبِي مَقَامَ الْخِزْيِ بِفِنَائِكَ، فَإِنْ سَكَتُّ لَمْ يَنْطِقْ عَنِّي أَحَدٌ، وَإِنْ شَفَعْتُ فَلَسْتُ بِأَهْلِ الشَّفَاعَةِ.',
 'زیرا ای پروردگارم، گناهانم مرا در آستانه‌ات در جایگاه رسوایی نشانده است؛ اگر خاموش بمانم کسی از سوی من سخن نمی‌گوید، و اگر شفاعت بخواهم، سزاوار شفاعت نیستم.'),
('اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَشَفِّعْ فِي خَطَايَايَ كَرَمَكَ، وَعُدْ عَلَى سَيِّئَاتِي بِعَفْوِكَ، وَلَا تَجْزِنِي جَزَائِي مِنْ عُقُوبَتِكَ،',
 'خدایا، بر محمد و خاندانش درود فرست، و کَرَمت را دربارهٔ خطاهایم شفیع گردان، و با گذشتت بر بدی‌هایم بازگرد، و مرا به سزایی که از کیفرت در خور آنم کیفر مده؛'),
('وَابْسُطْ عَلَيَّ طَوْلَكَ، وَجَلِّلْنِي بِسِتْرِكَ، وَافْعَلْ بِي فِعْلَ عَزِيزٍ تَضَرَّعَ إِلَيْهِ عَبْدٌ ذَلِيلٌ فَرَحِمَهُ، أَوْ غَنِيٍّ تَعَرَّضَ لَهُ عَبْدٌ فَقِيرٌ فَنَعَشَهُ.',
 'و احسانت را بر من بگستران، و با پوششت سراپایم را بپوشان، و با من چنان کن که عزیزی کند که بنده‌ای خوار به درگاهش زاری کرد و بر او رحم آورد، یا توانگری که بنده‌ای نیازمند خود را در برابرش نهاد و او را برپا داشت.'),
('اللَّهُمَّ لَا خَفِيرَ لِي مِنْكَ فَلْيَخْفُرْنِي عِزُّكَ، وَلَا شَفِيعَ لِي إِلَيْكَ فَلْيَشْفَعْ لِي فَضْلُكَ، وَقَدْ أَوْجَلَتْنِي خَطَايَايَ فَلْيُؤْمِنِّي عَفْوُكَ.',
 'خدایا، در برابر تو پناه‌دهنده‌ای ندارم، پس عزّتت پناهم دهد؛ و نزد تو شفیعی ندارم، پس فضلت شفیعم شود؛ و خطاهایم مرا ترسانده است، پس گذشتت ایمنم کند.'),
('فَمَا كُلُّ مَا نَطَقْتُ بِهِ عَنْ جَهْلٍ مِنِّي بِسُوءِ أَثَرِي، وَلَا نِسْيَانٍ لِمَا سَبَقَ مِنْ ذَمِيمِ فِعْلِي،',
 'آنچه گفتم از روی نادانی‌ام به کارنامهٔ بدم، و فراموشیِ کردار نکوهیده‌ای که از من گذشت، نبود؛'),
('لَكِنْ لِتَسْمَعَ سَمَاؤُكَ وَمَنْ فِيهَا، وَأَرْضُكَ وَمَنْ عَلَيْهَا، مَا أَظْهَرْتُ لَكَ مِنَ النَّدَمِ، وَلَجَأْتُ إِلَيْكَ فِيهِ مِنَ التَّوْبَةِ،',
 'بلکه برای اینکه آسمانت و هر که در آن است، و زمینت و هر که بر آن است، بشنوند آنچه از پشیمانی برایت آشکار کردم، و توبه‌ای را که در آن به تو پناه آوردم؛'),
('فَلَعَلَّ بَعْضَهُمْ بِرَحْمَتِكَ يَرْحَمُنِي لِسُوءِ مَوْقِفِي، أَوْ تُدْرِكُهُ الرِّقَّةُ عَلَيَّ لِسُوءِ حَالِي، فَيَنَالَنِي مِنْهُ بِدَعْوَةٍ هِيَ أَسْمَعُ لَدَيْكَ مِنْ دُعَائِي، أَوْ شَفَاعَةٍ أَوْكَدُ عِنْدَكَ مِنْ شَفَاعَتِي، تَكُونُ بِهَا نَجَاتِي مِنْ غَضَبِكَ، وَفَوْزَتِي بِرِضَاكَ.',
 'تا شاید یکی از آنان به رحمت تو، به خاطر بدیِ جایگاهم بر من رحم کند، یا به خاطر بدیِ حالم دلش بر من بسوزد، و از او دعایی به من برسد که نزد تو شنیده‌تر از دعای من باشد، یا شفاعتی که نزد تو استوارتر از شفاعت من باشد؛ که رهایی‌ام از خشمت و کامیابی‌ام به خشنودی‌ات با آن باشد.'),
('اللَّهُمَّ إِنْ يَكُنِ النَّدَمُ تَوْبَةً إِلَيْكَ فَأَنَا أَنْدَمُ النَّادِمِينَ، وَإِنْ يَكُنِ التَّرْكُ لِمَعْصِيَتِكَ إِنَابَةً فَأَنَا أَوَّلُ الْمُنِيبِينَ، وَإِنْ يَكُنِ الِاسْتِغْفَارُ حِطَّةً لِلذُّنُوبِ فَإِنِّي لَكَ مِنَ الْمُسْتَغْفِرِينَ.',
 'خدایا، اگر پشیمانی توبه به سوی توست، من پشیمان‌ترینِ پشیمانانم؛ و اگر ترکِ نافرمانی‌ات بازگشت [به تو] است، من نخستینِ بازگشت‌کنندگانم؛ و اگر آمرزش‌خواهی ریزانندهٔ گناهان است، من از آمرزش‌خواهانِ درگاه توام.'),
('اللَّهُمَّ فَكَمَا أَمَرْتَ بِالتَّوْبَةِ، وَضَمِنْتَ الْقَبُولَ، وَحَثَثْتَ عَلَى الدُّعَاءِ، وَوَعَدْتَ الْإِجَابَةَ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاقْبَلْ تَوْبَتِي، وَلَا تَرْجِعْنِي مَرْجِعَ الْخَيْبَةِ مِنْ رَحْمَتِكَ، إِنَّكَ أَنْتَ التَّوَّابُ عَلَى الْمُذْنِبِينَ، وَالرَّحِيمُ لِلْخَاطِئِينَ الْمُنِيبِينَ.',
 'خدایا، پس همان‌گونه که به توبه فرمان دادی، و پذیرفتن را ضمانت کردی، و به دعا برانگیختی، و اجابت را وعده دادی، بر محمد و خاندانش درود فرست، و توبه‌ام را بپذیر، و مرا از رحمتت نومیدانه بازمگردان؛ همانا تویی که بر گناهکاران بسیار توبه‌پذیری، و بر خطاکارانِ بازگشته مهربانی.'),
('اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ كَمَا هَدَيْتَنَا بِهِ، وَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ كَمَا اسْتَنْقَذْتَنَا بِهِ، وَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ صَلَاةً تَشْفَعُ لَنَا يَوْمَ الْقِيَامَةِ وَيَوْمَ الْفَاقَةِ إِلَيْكَ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَهُوَ عَلَيْكَ يَسِيرٌ.',
 'خدایا، بر محمد و خاندانش درود فرست، چنان‌که ما را به وسیلهٔ او هدایت کردی؛ و بر محمد و خاندانش درود فرست، چنان‌که ما را به وسیلهٔ او [از گمراهی] رهانیدی؛ و بر محمد و خاندانش درودی فرست که روز قیامت و روزِ نیاز به تو، برای ما شفاعت کند؛ همانا تو بر هر چیزی توانایی، و این بر تو آسان است.'),
])

D[16] = dict(title='دعای طلب عفو از گناهان', sub='زاری برای بخشش گناهان و عیب‌ها',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا اسْتَقَالَ مِنْ ذُنُوبِهِ، أَوْ تَضَرَّعَ فِي طَلَبِ الْعَفْوِ عَنْ عُيُوبِهِ',
 intro_fa='از دعاهای امام سجاد (ع) هنگامی که از گناهانش درگذشت می‌خواست، یا برای بخشیده شدن عیب‌هایش زاری می‌کرد',
 p=[
('اللَّهُمَّ يَا مَنْ بِرَحْمَتِهِ يَسْتَغِيثُ الْمُذْنِبُونَ، وَيَا مَنْ إِلَى ذِكْرِ إِحْسَانِهِ يَفْزَعُ الْمُضْطَرُّونَ، وَيَا مَنْ لِخِيفَتِهِ يَنْتَحِبُ الْخَاطِئُونَ،',
 'خدایا، ای که گناهکاران به رحمتش پناه می‌برند، و ای که درماندگان به یادِ نیکی‌اش رو می‌آورند، و ای که خطاکاران از ترسش با صدای بلند می‌گریند؛'),
('يَا أُنْسَ كُلِّ مُسْتَوْحِشٍ غَرِيبٍ، وَيَا فَرَجَ كُلِّ مَكْرُوبٍ كَئِيبٍ، وَيَا غَوْثَ كُلِّ مَخْذُولٍ فَرِيدٍ، وَيَا عَضُدَ كُلِّ مُحْتَاجٍ طَرِيدٍ،',
 'ای همدمِ هر غریبِ هراسان، و ای گشایشِ هر اندوهگینِ دل‌گرفته، و ای فریادرسِ هر تنهای بی‌یاور، و ای پشتیبانِ هر نیازمندِ رانده‌شده؛'),
('أَنْتَ الَّذِي وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْماً، وَأَنْتَ الَّذِي جَعَلْتَ لِكُلِّ مَخْلُوقٍ فِي نِعَمِكَ سَهْماً، وَأَنْتَ الَّذِي عَفْوُهُ أَعْلَى مِنْ عِقَابِهِ، وَأَنْتَ الَّذِي تَسْعَى رَحْمَتُهُ أَمَامَ غَضَبِهِ،',
 'تویی که رحمت و دانشت همه چیز را فرا گرفته، و تویی که برای هر آفریده‌ای در نعمت‌هایت سهمی نهاده‌ای، و تویی که گذشتش برتر از کیفرش است، و تویی که رحمتش پیشاپیشِ خشمش می‌رود؛'),
('وَأَنْتَ الَّذِي عَطَاؤُهُ أَكْثَرُ مِنْ مَنْعِهِ، وَأَنْتَ الَّذِي اتَّسَعَ الْخَلَائِقُ كُلُّهُمْ فِي وُسْعِهِ، وَأَنْتَ الَّذِي لَا يَرْغَبُ فِي جَزَاءِ مَنْ أَعْطَاهُ، وَأَنْتَ الَّذِي لَا يُفْرِطُ فِي عِقَابِ مَنْ عَصَاهُ.',
 'و تویی که بخششش از دریغش بیشتر است، و تویی که همهٔ آفریدگان در گستردگی‌اش جا گرفته‌اند، و تویی که به پاداش گرفتن از کسی که به او بخشیده چشم ندارد، و تویی که در کیفرِ کسی که نافرمانی‌اش کرده زیاده‌روی نمی‌کند.'),
('وَأَنَا يَا إِلَهِي عَبْدُكَ الَّذِي أَمَرْتَهُ بِالدُّعَاءِ فَقَالَ: لَبَّيْكَ وَسَعْدَيْكَ، هَا أَنَا ذَا يَا رَبِّ مَطْرُوحٌ بَيْنَ يَدَيْكَ،',
 'و من، ای معبودم، همان بنده‌ات هستم که او را به دعا فرمان دادی و گفت: «لبّیک و سعدیک [= فرمان‌بردارم و آماده‌ام]». اینک من، ای پروردگارم، در برابرت افتاده‌ام؛'),
('أَنَا الَّذِي أَوْقَرَتِ الْخَطَايَا ظَهْرَهُ، وَأَنَا الَّذِي أَفْنَتِ الذُّنُوبُ عُمُرَهُ، وَأَنَا الَّذِي بِجَهْلِهِ عَصَاكَ، وَلَمْ تَكُنْ أَهْلاً مِنْهُ لِذَاكَ.',
 'منم آنکه خطاها پشتش را گران‌بار کرده، و منم آنکه گناهان عمرش را تباه کرده، و منم آنکه از روی نادانی تو را نافرمانی کرد، در حالی که تو سزاوار چنین [رفتاری] از او نبودی.'),
('هَلْ أَنْتَ يَا إِلَهِي رَاحِمٌ مَنْ دَعَاكَ فَأُبْلِغَ فِي الدُّعَاءِ؟ أَمْ أَنْتَ غَافِرٌ لِمَنْ بَكَاكَ فَأُسْرِعَ فِي الْبُكَاءِ؟ أَمْ أَنْتَ مُتَجَاوِزٌ عَمَّنْ عَفَّرَ لَكَ وَجْهَهُ تَذَلُّلاً؟ أَمْ أَنْتَ مُغْنٍ مَنْ شَكَا إِلَيْكَ فَقْرَهُ تَوَكُّلاً؟',
 'آیا، ای معبودم، بر کسی که تو را بخواند رحم می‌کنی، تا در دعا بکوشم؟ یا کسی را که برایت بگرید می‌آمرزی، تا در گریستن بشتابم؟ یا از کسی که از روی خواری چهره‌اش را برایت به خاک بساید درمی‌گذری؟ یا کسی را که از روی توکل از فقرش به تو شکایت کند بی‌نیاز می‌کنی؟'),
('إِلَهِي لَا تُخَيِّبْ مَنْ لَا يَجِدُ مُعْطِياً غَيْرَكَ، وَلَا تَخْذُلْ مَنْ لَا يَسْتَغْنِي عَنْكَ بِأَحَدٍ دُونَكَ.',
 'معبودا، کسی را که بخشنده‌ای جز تو نمی‌یابد ناامید مکن، و کسی را که با هیچ کس جز تو از تو بی‌نیاز نمی‌شود بی‌یاور مگذار.'),
('إِلَهِي فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تُعْرِضْ عَنِّي وَقَدْ أَقْبَلْتُ عَلَيْكَ، وَلَا تَحْرِمْنِي وَقَدْ رَغِبْتُ إِلَيْكَ، وَلَا تَجْبَهْنِي بِالرَّدِّ وَقَدِ انْتَصَبْتُ بَيْنَ يَدَيْكَ.',
 'معبودا، پس بر محمد و خاندانش درود فرست، و از من روی مگردان در حالی که به تو رو آورده‌ام، و محرومم مکن در حالی که به تو اشتیاق یافته‌ام، و با رد کردن به رویم مزن در حالی که در برابرت برپا ایستاده‌ام.'),
('أَنْتَ الَّذِي وَصَفْتَ نَفْسَكَ بِالرَّحْمَةِ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ وَارْحَمْنِي، وَأَنْتَ الَّذِي سَمَّيْتَ نَفْسَكَ بِالْعَفْوِ فَاعْفُ عَنِّي.',
 'تویی که خود را به رحمت وصف کرده‌ای، پس بر محمد و خاندانش درود فرست و بر من رحم کن؛ و تویی که خود را «بسیار گذشت‌کننده» نامیده‌ای، پس از من درگذر.'),
('قَدْ تَرَى يَا إِلَهِي فَيْضَ دَمْعِي مِنْ خِيفَتِكَ، وَوَجِيبَ قَلْبِي مِنْ خَشْيَتِكَ، وَانْتِقَاضَ جَوَارِحِي مِنْ هَيْبَتِكَ،',
 'ای معبودم، تو جاری شدن اشکم را از ترست، و تپش دلم را از بیمت، و لرزش اندامم را از هیبتت می‌بینی؛'),
('كُلُّ ذَلِكَ حَيَاءٌ مِنْكَ لِسُوءِ عَمَلِي، وَلِذَاكَ خَمَدَ صَوْتِي عَنِ الْجَأْرِ إِلَيْكَ، وَكَلَّ لِسَانِي عَنْ مُنَاجَاتِكَ.',
 'همهٔ این‌ها از شرم از توست به خاطر بدیِ کردارم؛ و از همین رو صدایم از ناله کردن به درگاهت خاموش شده، و زبانم از راز گفتن با تو درمانده است.'),
('يَا إِلَهِي فَلَكَ الْحَمْدُ، فَكَمْ مِنْ عَائِبَةٍ سَتَرْتَهَا عَلَيَّ فَلَمْ تَفْضَحْنِي، وَكَمْ مِنْ ذَنْبٍ غَطَّيْتَهُ عَلَيَّ فَلَمْ تَشْهَرْنِي، وَكَمْ مِنْ شَائِبَةٍ أَلْمَمْتُ بِهَا فَلَمْ تَهْتِكْ عَنِّي سِتْرَهَا،',
 'ای معبودم، پس ستایش از آنِ توست؛ چه بسیار عیبی که بر من پوشاندی و رسوایم نکردی، و چه بسیار گناهی که بر من پنهان داشتی و انگشت‌نمایم نکردی، و چه بسیار آلودگی‌ای که به آن دست زدم و پرده‌اش را از من ندریدی؛'),
('وَلَمْ تُقَلِّدْنِي مَكْرُوهَ شَنَارِهَا، وَلَمْ تُبْدِ سَوْءَاتِهَا لِمَنْ يَلْتَمِسُ مَعَايِبِي مِنْ جِيرَتِي، وَحَسَدَةِ نِعْمَتِكَ عِنْدِي،',
 'و ننگِ ناخوشایندش را به گردنم نیاویختی، و زشتی‌هایش را برای همسایگانم که در پی عیب‌هایم بودند، و حسودانِ نعمتی که نزد من داری، آشکار نکردی؛'),
('ثُمَّ لَمْ يَنْهَنِي ذَلِكَ عَنْ أَنْ جَرَيْتُ إِلَى سُوءِ مَا عَهِدْتَ مِنِّي!',
 'سپس این [پرده‌پوشی] مرا باز نداشت از اینکه به سوی همان بدی‌ای که از من سراغ داشتی بشتابم!'),
('فَمَنْ أَجْهَلُ مِنِّي يَا إِلَهِي بِرُشْدِهِ؟ وَمَنْ أَغْفَلُ مِنِّي عَنْ حَظِّهِ؟ وَمَنْ أَبْعَدُ مِنِّي مِنِ اسْتِصْلَاحِ نَفْسِهِ، حِينَ أُنْفِقُ مَا أَجْرَيْتَ عَلَيَّ مِنْ رِزْقِكَ فِيمَا نَهَيْتَنِي عَنْهُ مِنْ مَعْصِيَتِكَ؟',
 'پس ای معبودم، چه کسی از من به خیرِ خود نادان‌تر است؟ و چه کسی از من از بهرهٔ خود غافل‌تر است؟ و چه کسی از من از اصلاح خویش دورتر است، آنگاه که روزی‌ای را که بر من روان کردی، در نافرمانی‌ای که مرا از آن نهی کردی خرج می‌کنم؟'),
('وَمَنْ أَبْعَدُ غَوْراً فِي الْبَاطِلِ، وَأَشَدُّ إِقْدَاماً عَلَى السُّوءِ مِنِّي، حِينَ أَقِفُ بَيْنَ دَعْوَتِكَ وَدَعْوَةِ الشَّيْطَانِ، فَأَتَّبِعُ دَعْوَتَهُ عَلَى غَيْرِ عَمًى مِنِّي فِي مَعْرِفَةٍ بِهِ، وَلَا نِسْيَانٍ مِنْ حِفْظِي لَهُ؟',
 'و چه کسی از من در باطل فرورفته‌تر، و در اقدام به بدی گستاخ‌تر است، آنگاه که میان دعوت تو و دعوت شیطان می‌ایستم و دعوت او را پیروی می‌کنم، بی‌آنکه در شناختن او کور باشم، یا آنچه را از او می‌دانم فراموش کرده باشم؟'),
('وَأَنَا حِينَئِذٍ مُوقِنٌ بِأَنَّ مُنْتَهَى دَعْوَتِكَ إِلَى الْجَنَّةِ، وَمُنْتَهَى دَعْوَتِهِ إِلَى النَّارِ.',
 'و من در آن هنگام یقین دارم که پایانِ دعوت تو به بهشت است، و پایانِ دعوت او به آتش.'),
('سُبْحَانَكَ مَا أَعْجَبَ مَا أَشْهَدُ بِهِ عَلَى نَفْسِي، وَأُعَدِّدُهُ مِنْ مَكْتُومِ أَمْرِي! وَأَعْجَبُ مِنْ ذَلِكَ أَنَاتُكَ عَنِّي، وَإِبْطَاؤُكَ عَنْ مُعَاجَلَتِي،',
 'پاکی از آنِ توست! چه شگفت است آنچه بر ضد خود به آن گواهی می‌دهم، و از کارهای پنهانم برمی‌شمارم! و شگفت‌تر از آن، درنگ و بردباری تو با من، و دیر کردنت در شتاب [به کیفرِ] من است؛'),
('وَلَيْسَ ذَلِكَ مِنْ كَرَمِي عَلَيْكَ، بَلْ تَأَنِّياً مِنْكَ لِي، وَتَفَضُّلاً مِنْكَ عَلَيَّ؛ لِأَنْ أَرْتَدِعَ عَنْ مَعْصِيَتِكَ الْمُسْخِطَةِ، وَأُقْلِعَ عَنْ سَيِّئَاتِي الْمُخْلِقَةِ، وَلِأَنَّ عَفْوَكَ عَنِّي أَحَبُّ إِلَيْكَ مِنْ عُقُوبَتِي.',
 'و این از ارجمندیِ من نزد تو نیست، بلکه از درنگ تو با من و بخشش تو بر من است؛ تا از نافرمانیِ خشم‌آورت باز ایستم، و از بدی‌هایم که [آبرو را] کهنه و فرسوده می‌کنند دست بکشم؛ و از آن روست که گذشتن از من نزد تو از کیفر کردنم محبوب‌تر است.'),
('بَلْ أَنَا يَا إِلَهِي أَكْثَرُ ذُنُوباً، وَأَقْبَحُ آثَاراً، وَأَشْنَعُ أَفْعَالاً، وَأَشَدُّ فِي الْبَاطِلِ تَهَوُّراً، وَأَضْعَفُ عِنْدَ طَاعَتِكَ تَيَقُّظاً، وَأَقَلُّ لِوَعِيدِكَ انْتِبَاهاً وَارْتِقَاباً، مِنْ أَنْ أُحْصِيَ لَكَ عُيُوبِي، أَوْ أَقْدِرَ عَلَى ذِكْرِ ذُنُوبِي.',
 'بلکه ای معبودم، گناهانم بیشتر، و کارنامه‌ام زشت‌تر، و کارهایم ناپسندتر، و بی‌پروایی‌ام در باطل شدیدتر، و بیداری‌ام هنگام فرمان‌بری‌ات ضعیف‌تر، و هشیاری و چشم‌به‌راهی‌ام نسبت به هشدارت کمتر از آن است که بتوانم عیب‌هایم را برایت برشمارم، یا بر یاد کردنِ گناهانم توانا باشم.'),
('وَإِنَّمَا أُوَبِّخُ بِهَذَا نَفْسِي طَمَعاً فِي رَأْفَتِكَ الَّتِي بِهَا صَلَاحُ أَمْرِ الْمُذْنِبِينَ، وَرَجَاءً لِرَحْمَتِكَ الَّتِي بِهَا فَكَاكُ رِقَابِ الْخَاطِئِينَ.',
 'و جز این نیست که با این [سخنان] خود را سرزنش می‌کنم، به طمعِ مهربانی‌ات که اصلاح کار گناهکاران به آن است، و به امیدِ رحمتت که رهایی گردن‌های خطاکاران به آن است.'),
('اللَّهُمَّ وَهَذِهِ رَقَبَتِي قَدْ أَرَقَّتْهَا الذُّنُوبُ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ وَأَعْتِقْهَا بِعَفْوِكَ، وَهَذَا ظَهْرِي قَدْ أَثْقَلَتْهُ الْخَطَايَا، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ وَخَفِّفْ عَنْهُ بِمَنِّكَ.',
 'خدایا، این گردن من است که گناهان آن را به بند بردگی کشیده؛ پس بر محمد و خاندانش درود فرست و با گذشتت آزادش کن. و این پشت من است که خطاها سنگینش کرده؛ پس بر محمد و خاندانش درود فرست و با احسانت آن را سبک کن.'),
('يَا إِلَهِي لَوْ بَكَيْتُ إِلَيْكَ حَتَّى تَسْقُطَ أَشْفَارُ عَيْنَيَّ، وَانْتَحَبْتُ حَتَّى يَنْقَطِعَ صَوْتِي، وَقُمْتُ لَكَ حَتَّى تَتَنَشَّرَ قَدَمَايَ، وَرَكَعْتُ لَكَ حَتَّى يَنْخَلِعَ صُلْبِي، وَسَجَدْتُ لَكَ حَتَّى تَتَفَقَّأَ حَدَقَتَايَ،',
 'ای معبودم، اگر به درگاهت چندان بگریم که مژه‌های چشمانم بریزد، و چندان با صدا بنالم که صدایم بند آید، و چندان برایت [به نماز] بایستم که پاهایم ورم کند، و چندان برایت رکوع کنم که ستون پشتم از جا درآید، و چندان برایت سجده کنم که حدقه‌های چشمانم بترکد،'),
('وَأَكَلْتُ تُرَابَ الْأَرْضِ طُولَ عُمُرِي، وَشَرِبْتُ مَاءَ الرَّمَادِ آخِرَ دَهْرِي، وَذَكَرْتُكَ فِي خِلَالِ ذَلِكَ حَتَّى يَكِلَّ لِسَانِي، ثُمَّ لَمْ أَرْفَعْ طَرْفِي إِلَى آفَاقِ السَّمَاءِ اسْتِحْيَاءً مِنْكَ،',
 'و همهٔ عمرم خاک زمین بخورم، و تا پایان روزگارم آبِ خاکسترآلود بنوشم، و در این میان چندان یادت کنم که زبانم درمانده شود، سپس از شرم تو چشمم را به کرانه‌های آسمان بالا نبرم،'),
('مَا اسْتَوْجَبْتُ بِذَلِكَ مَحْوَ سَيِّئَةٍ وَاحِدَةٍ مِنْ سَيِّئَاتِي.',
 'با این همه، پاک شدنِ حتی یک بدی از بدی‌هایم را سزاوار نشده‌ام.'),
('وَإِنْ كُنْتَ تَغْفِرُ لِي حِينَ أَسْتَوْجِبُ مَغْفِرَتَكَ، وَتَعْفُو حِينَ أَسْتَحِقُّ عَفْوَكَ، فَإِنَّ ذَلِكَ غَيْرُ وَاجِبٍ لِي بِاسْتِحْقَاقٍ، وَلَا أَنَا أَهْلٌ لَهُ بِاسْتِيجَابٍ،',
 'و اگر هم هنگامی که سزاوار آمرزشت شوم مرا بیامرزی، و هنگامی که مستحق گذشتت شوم درگذری، این [حقی] نیست که به سبب شایستگی برایم واجب باشد، و من به سبب سزاواری اهل آن نیستم؛'),
('إِذْ كَانَ جَزَائِي مِنْكَ فِي أَوَّلِ مَا عَصَيْتُكَ النَّارَ، فَإِنْ تُعَذِّبْنِي فَأَنْتَ غَيْرُ ظَالِمٍ لِي.',
 'زیرا سزای من از سوی تو، از نخستین باری که نافرمانی‌ات کردم، آتش بود؛ پس اگر عذابم کنی، بر من ستمکار نیستی.'),
('إِلَهِي فَإِذْ قَدْ تَغَمَّدْتَنِي بِسِتْرِكَ فَلَمْ تَفْضَحْنِي، وَتَأَنَّيْتَنِي بِكَرَمِكَ فَلَمْ تُعَاجِلْنِي، وَحَلُمْتَ عَنِّي بِتَفَضُّلِكَ فَلَمْ تُغَيِّرْ نِعْمَتَكَ عَلَيَّ، وَلَمْ تُكَدِّرْ مَعْرُوفَكَ عِنْدِي،',
 'معبودا، پس اکنون که مرا در پوشش خود فرو پوشاندی و رسوایم نکردی، و با کَرَمت با من درنگ کردی و [در کیفرم] شتاب نکردی، و با بخششت بر من بردباری کردی و نعمتت را بر من دگرگون نکردی، و نیکی‌ات را نزد من تیره نساختی،'),
('فَارْحَمْ طُولَ تَضَرُّعِي، وَشِدَّةَ مَسْكَنَتِي، وَسُوءَ مَوْقِفِي.',
 'پس بر زاریِ طولانی‌ام، و سختیِ بیچارگی‌ام، و بدیِ جایگاهم رحم کن.'),
('اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَقِنِي مِنَ الْمَعَاصِي، وَاسْتَعْمِلْنِي بِالطَّاعَةِ، وَارْزُقْنِي حُسْنَ الْإِنَابَةِ، وَطَهِّرْنِي بِالتَّوْبَةِ، وَأَيِّدْنِي بِالْعِصْمَةِ، وَاسْتَصْلِحْنِي بِالْعَافِيَةِ،',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا از گناهان نگاه دار، و به فرمان‌برداری به کار گیر، و بازگشتِ نیکو [به سوی خودت] را روزی‌ام کن، و با توبه پاکم گردان، و با نگه‌داری [از گناه] یاری‌ام کن، و با عافیت اصلاحم کن؛'),
('وَأَذِقْنِي حَلَاوَةَ الْمَغْفِرَةِ، وَاجْعَلْنِي طَلِيقَ عَفْوِكَ، وَعَتِيقَ رَحْمَتِكَ، وَاكْتُبْ لِي أَمَاناً مِنْ سُخْطِكَ،',
 'و شیرینیِ آمرزش را به من بچشان، و مرا آزادشدهٔ گذشتت و رهاشدهٔ رحمتت قرار ده، و برایم امان‌نامه‌ای از خشمت بنویس؛'),
('وَبَشِّرْنِي بِذَلِكَ فِي الْعَاجِلِ دُونَ الْآجِلِ، بُشْرَى أَعْرِفُهَا، وَعَرِّفْنِي فِيهِ عَلَامَةً أَتَبَيَّنُهَا،',
 'و مرا به این [آمرزش] در همین دنیا، نه در آینده، بشارت ده؛ بشارتی که آن را بشناسم؛ و در این باره نشانه‌ای به من بشناسان که آن را آشکارا ببینم؛'),
('إِنَّ ذَلِكَ لَا يَضِيقُ عَلَيْكَ فِي وُسْعِكَ، وَلَا يَتَكَأَّدُكَ فِي قُدْرَتِكَ، وَلَا يَتَصَعَّدُكَ فِي أَنَاتِكَ، وَلَا يَؤُودُكَ فِي جَزِيلِ هِبَاتِكَ الَّتِي دَلَّتْ عَلَيْهَا آيَاتُكَ،',
 'همانا این [کار] در گستردگی‌ات بر تو تنگ نمی‌آید، و در قدرتت تو را به رنج نمی‌افکند، و در بردباری‌ات بر تو دشوار نیست، و در بخشش‌های فراوانت که نشانه‌هایت بر آن گواهی می‌دهند، تو را خسته نمی‌کند؛'),
('إِنَّكَ تَفْعَلُ مَا تَشَاءُ، وَتَحْكُمُ مَا تُرِيدُ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.',
 'همانا تو هر چه بخواهی انجام می‌دهی، و هر چه اراده کنی حکم می‌کنی؛ همانا تو بر هر چیزی توانایی.'),
])
